from onbellek import onbellekle

calls=[]
@onbellekle()
def g(a,b,c_=None): calls.append((a,b,c_)); return a+b+c_
g(1,2,c_=3); g(1,2,c_=3)  # identical kwargs -> hit
assert len(calls)==1 and g.bilgi()=={"isabet":1,"iska":1}

# separate caches per function (keys may collide across functions: kare(3) vs h(3))
@onbellekle()
def h(x): return x*10
h(3); h(3)
assert h.bilgi()=={"isabet":1,"iska":1}

# non-hashable args run directly, never cached
@onbellekle()
def topla(l): return sum(l)
toplama=[0]
orig=topla
def spy(l): global topalma; topalma+=1; return sum(l)
assert topla([1,2])==3 and topla([1,2])==3 and topla.bilgi()=={"isabet":0,"iska":2}

# ttl boundary with fake clock
t=[0.0]; saat=lambda: t[0]
n=[0]
@onbellekle(ttl=5, saat=saat)
def f(x): n.append(1); return x+1
f(1)          # iska @0
t[0]=5.0; f(1)  # exactly ttl -> still valid (hit)
assert n==[1], "tam ttl anında hâlâ geçerli"
t[0]=5.001; f(1) # after ttl -> recompute
assert n==[1,1] and f.bilgi()=={"isabet":1,"iska":2}

# temizle clears only its own cache
f.temizle(); t[0]=5.001; f(1)
assert len(n)==3  # recomputed after clear
kare_c=[0]
@onbellekle()
def k(x): return x*2
k(9); k(9)
h.bilgi()  # ensure h's cache untouched by others' temizle (no error, still hit on repeat)
assert h(3)==30 and h.bilgi()=={"isabet":2,"iska":1}

# wraps: name + docstring preserved
@onbellekle()
def adli(x):
    """belge"""
    return x
import functools as F
assert adli.__name__=="adli" and adli.__doc__=="belge"

print("TÜM EK TESTLER GEÇTİ")

