# fresh function for non-hashable check
@onbellekle()
def topla(l): return sum(l)
assert topla([1,2])==3 and topla([1,2])==3
assert topla.bilgi()=={"isabet":0,"iska":2}, topla.bilgi()

# separate caches per function (kare(3) vs h(3) same key shape must not collide)
@onbellekle()
def k(x): return x*2
k(9); k(9)
assert k.bilgi()=={"isabet":1,"iska":1}

# ttl boundary
t=[0.0]; saat=lambda: t[0]
n=0
@onbellekle(ttl=5, saat=saat)
def f(x):
    global n; n+=1; return x+1
f(1); assert n==1
t[0]=5.0; f(1); assert n==1, "tam ttl anında hâlâ geçerli"
t[0]=5.001; f(1); assert n==2 and f.bilgi()=={"isabet":1,"iska":2}

# temizle clears only own cache
f.temizle(); t[0]=6.0; f(1); assert n==3
assert k(9)==18 and k.bilgi()["isabet"]==2  # k unaffected by f.temizle()

@onbellekle()
def adli(x):
    """belge"""
    return x
assert adli.__name__=="adli" and adli.__doc__=="belge"
